def clenshaw_curtis(f, a=-1, b=1, n=1024, **kwargs):
    fun = _callable(f)

    def wrapped(x):
        return fun(x, **kwargs)

    a = float(a)
    b = float(b)
    if a == b:
        return np.float64(0.0)
    if not math.isfinite(_one(wrapped(a))):
        a = a + _EPS * math.copysign(1.0, b - a)
    if not math.isfinite(_one(wrapped(b))):
        b = b - _EPS * math.copysign(1.0, b - a)
    degree = int(n)
    x = np.cos(math.pi * np.arange(0, degree + 1) / degree)
    fx = np.asarray(wrapped(0.5 * ((b - a) * x + (b + a))), dtype=float).reshape(-1) / (2.0 * degree)
    order = np.concatenate([np.arange(0, degree + 1), np.arange(degree - 1, 0, -1)])
    g = np.fft.fft(fx[order]).real
    second = g[1:degree] + g[(2 * degree - 1):degree:-1]
    d = np.concatenate([np.array([g[0]]), second, np.array([g[degree]])])
    w = np.zeros(degree + 1)
    positions = np.arange(1, degree + 2, 2)
    evens = np.arange(0, degree + 1, 2, dtype=float)
    w[positions - 1] = 2.0 / (1.0 - evens ** 2)
    return np.float64(np.sum(w * d) * (b - a) / 2.0)


def quadgk(f, a, b, tol=None, **kwargs):
    a = _scalar(a, "a")
    b = _scalar(b, "b")
    if tol is None:
        tol = _EPS ** 0.5
    fun = _callable(f)

    def wrapped(x):
        return fun(x, **kwargs)

    if a == b:
        return np.float64(0.0)
    if a > b:
        return np.float64(-quadgk(wrapped, b, a, tol=tol))
    return np.float64(_gkadpt(wrapped, a, b, float(tol)))


def quadcc(f, a, b, tol=None, **kwargs):
    a = _scalar(a, "a")
    b = _scalar(b, "b")
    if tol is None:
        tol = _EPS ** 0.5
    fun = _callable(f)

    def wrapped(x):
        return fun(x, **kwargs)

    if a == b:
        return np.float64(0.0)
    if a > b:
        return np.float64(-quadgk(wrapped, b, a, tol=tol))
    if not math.isfinite(_one(wrapped(a))):
        a = a + _EPS * math.copysign(1.0, b - a)
    if not math.isfinite(_one(wrapped(b))):
        b = b - _EPS * math.copysign(1.0, b - a)
    return np.float64(_ccadpt(wrapped, a, b, float(tol)))


def simpadpt(f, a, b, tol=1e-6, **kwargs):
    a = _scalar(a, "a")
    b = _scalar(b, "b")
    fun = _callable(f)

    def wrapped(x):
        return fun(x, **kwargs)

    if a == b:
        return np.float64(0.0)
    if a > b:
        return np.float64(-simpadpt(wrapped, b, a, tol=tol))
    h = (b - a) / 8.0
    x = np.array([a, a + h, a + 2.0 * h, (a + b) / 2.0, b - 2.0 * h, b - h, b])
    y = np.array([_one(wrapped(value)) for value in x])
    if not math.isfinite(y[0]):
        y[0] = _one(wrapped(a + _EPS * (b - a)))
    if not math.isfinite(y[6]):
        y[6] = _one(wrapped(b - _EPS * (b - a)))
    hmin = _EPS * (b - a) / 1024.0
    return np.float64(
        _simpadpt(wrapped, x[0], x[2], y[0], y[1], y[2], tol, hmin)
        + _simpadpt(wrapped, x[2], x[4], y[2], y[3], y[4], tol, hmin)
        + _simpadpt(wrapped, x[4], x[6], y[4], y[5], y[6], tol, hmin)
    )


def quadinf(f, xa, xb, tol=1e-12, **kwargs):
    xa = _scalar(xa, "xa")
    xb = _scalar(xb, "xb")
    tol = _scalar(tol, "tol")
    fun = _callable(f)

    def wrapped(x):
        return fun(x, **kwargs)

    if xa == xb:
        return {"Q": np.float64(0.0), "reltol": np.float64(0.0)}
    if xa > xb:
        raise PracmaError("For the integration limits 'xa <= xb' is required.")
    u = -1.0
    v = 1.0
    if math.isfinite(xa) and math.isfinite(xb):
        duv = (xb - xa) / (v - u)

        def ff(y, scale=duv, origin=xa, left=u):
            return scale * _one(wrapped(origin + scale * (y - left)))
    elif math.isfinite(xa) and math.isinf(xb):
        def ff(y, origin=xa, left=u, right=v):
            scale = (right - left) / (1.0 - y) ** 2
            z = (y - left) / (right - left)
            return scale * _one(wrapped(origin + z / (1.0 - z)))
    elif math.isinf(xa) and math.isfinite(xb):
        origin = -xb

        def ff(y, origin=origin, left=u, right=v):
            scale = (right - left) / (1.0 - y) ** 2
            z = (y - left) / (right - left)
            return scale * _one(wrapped(-(origin + z / (1.0 - z))))
    elif math.isinf(xa) and math.isinf(xb):
        def ff(y, left=u, right=v):
            z = math.pi * (y - left) / (right - left) - 0.5
            scale = (1.0 / math.cos(z) ** 2) * math.pi / (right - left)
            return scale * _one(wrapped(math.tan(z)))
    else:
        raise PracmaError("Other integration domains will be treated later.")
    nodes = [np.asarray(row, dtype=float) for row in NODES]
    weights = [np.asarray(row, dtype=float) for row in WEIGHTS]
    h = 0.5
    x = nodes[0]
    w = weights[0]
    s = w[6] * ff(float(x[6]))
    for j in range(6):
        s = s + w[j] * (ff(float(x[j])) + ff(float(-x[j])))
    total = s * h
    delta = 0.0
    k = 1
    for k in range(2, 8):
        x = nodes[k - 1]
        w = weights[k - 1]
        s = 0.0
        for j in range(w.size):
            s = s + w[j] * (ff(float(x[j])) + ff(float(-x[j])))
        h = h / 2.0
        new_total = s * h + total / 2.0
        delta = abs(new_total - total)
        total = new_total
        if delta < tol:
            break
    return {"Q": np.float64(total), "relerr": np.float64(delta), "niter": int(k)}


def integral(fun, xmin, xmax, method=None, no_intervals=8, random=False, reltol=1e-8, abstol=0, **kwargs):
    xmin = _scalar(xmin, "xmin")
    xmax = _scalar(xmax, "xmax")
    no_intervals = max(1, math.floor(float(no_intervals)))
    target = _callable(fun)

    def wrapped(x):
        return target(x, **kwargs)

    if np.asarray(wrapped(xmin)).size > 1 or np.asarray(wrapped(xmax)).size > 1:
        raise PracmaError("Function 'fun' is array-valued! Use 'quadv'.\n")
    trial = np.asarray(wrapped(np.array([xmin, xmax], dtype=float)))
    if trial.size != 2:
        def vectorized(x, inner=wrapped):
            values = np.asarray(x, dtype=float).reshape(-1)
            return np.array([_one(inner(value)) for value in values])

        wrapped = vectorized
    if xmin == xmax:
        return np.float64(0.0)
    chosen = _match_arg(method)
    tol = min(float(reltol), float(abstol)) if float(abstol) > 0 else float(reltol)
    if math.isinf(xmin) or math.isinf(xmax):
        return np.float64(quadinf(wrapped, xmin, xmax, tol=tol)["Q"])
    if random:
        draws = np.sort(np.random.random(no_intervals - 1))
        xs = np.concatenate([np.array([xmin]), (xmax - xmin) * draws + xmin, np.array([xmax])])
    else:
        xs = linspace(xmin, xmax, no_intervals + 1)
    total = 0.0
    if chosen == "Kronrod":
        for i in range(no_intervals):
            total = total + quadgk(wrapped, xs[i], xs[i + 1], tol=tol)
    elif chosen == "Clenshaw":
        for i in range(no_intervals):
            total = total + quadcc(wrapped, xs[i], xs[i + 1], tol=tol)
    elif chosen == "Simpson":
        for i in range(no_intervals):
            total = total + simpadpt(wrapped, xs[i], xs[i + 1], tol=tol)
    else:
        raise PracmaError("Unknown method; not available as integration routine.")
    return np.float64(total)


def line_integral(fun, waypoints, method=None, reltol=1e-8, **kwargs):
    points = np.asarray(waypoints)
    if points.dtype == bool or (
        points.size and not np.issubdtype(points.dtype, np.number) and not np.iscomplexobj(points)
    ):
        raise PracmaError("is.complex(waypoints) || is.numeric(waypoints) is not TRUE")
    if method is not None and not isinstance(method, str):
        raise PracmaError("is.null(method) || is.character(method) is not TRUE")
    points = np.array(points, dtype=complex).reshape(-1)
    if points.size <= 1:
        return np.complex128(0.0 + 0.0j)
    target = _callable(fun)

    def wrapped(z):
        return target(z, **kwargs)

    total = 0.0 + 0.0j
    for i in range(1, points.size):
        a = points[i - 1]
        b = points[i]
        step = b - a

        def real_part(t, origin=a, delta=step):
            values = np.asarray(wrapped(origin + np.asarray(t) * delta))
            return np.real(values).astype(float)

        def imag_part(t, origin=a, delta=step):
            values = np.asarray(wrapped(origin + np.asarray(t) * delta))
            return np.imag(values).astype(float)

        if method is None:
            real = _stats_integrate(real_part, 0.0, 1.0, subdivisions=300, rel_tol=reltol)
            imag = _stats_integrate(imag_part, 0.0, 1.0, subdivisions=300, rel_tol=reltol)
        else:
            real = integral(real_part, 0.0, 1.0, reltol=reltol, method=method)
            imag = integral(imag_part, 0.0, 1.0, reltol=reltol, method=method)
        total = total + step * (real + imag * 1j)
    return np.complex128(total)


def _gkadpt(f, a, b, tol):
    half = 0.5 * (b - a)
    mid = 0.5 * (a + b)
    q7 = float(np.sum(_W7 * np.asarray(f(mid + half * _N7), dtype=float).reshape(-1))) * half
    q15 = float(np.sum(_W15 * np.asarray(f(mid + half * _N15), dtype=float).reshape(-1))) * half
    if not math.isfinite(q7) or not math.isfinite(q15):
        return q15
    if abs(q15 - q7) < tol:
        return q15
    if abs(b - a) < 16.0 * _EPS:
        raise PracmaError("object 'Q2' not found")
    right = _gkadpt(f, mid, b, tol)
    left = _gkadpt(f, a, mid, tol)
    return left + right


def _ccadpt(f, a, b, tol):
    q4 = clenshaw_curtis(f, a, b, n=4)
    q8 = clenshaw_curtis(f, a, b, n=8)
    if abs(q4 - q8) < tol:
        return q8
    mid = 0.5 * (a + b)
    return _ccadpt(f, a, mid, tol) + _ccadpt(f, mid, b, tol)


def _simpadpt(f, a, b, fa, fc, fb, tol, hmin):
    h = b - a
    g = (a + b) / 2.0
    d = (a + g) / 2.0
    fd = _one(f(d))
    e = (g + b) / 2.0
    fe = _one(f(e))
    q1 = (h / 6.0) * (fa + 4.0 * fc + fb)
    q2 = (h / 12.0) * (fa + 4.0 * fd + 2.0 * fc + 4.0 * fe + fb)
    q = q2 + (q2 - q1) / 15.0
    if not math.isfinite(q):
        return q
    if abs(q2 - q) <= tol:
        return q
    if abs(h) < hmin or g == a or g == b:
        return q
    return _simpadpt(f, a, g, fa, fd, fc, tol, hmin) + _simpadpt(f, g, b, fc, fe, fb, tol, hmin)


def _stats_integrate(func, lower, upper, subdivisions=100, rel_tol=None, abs_tol=None):
    if rel_tol is None:
        rel_tol = _EPS ** 0.25
    if abs_tol is None:
        abs_tol = rel_tol
    a = float(lower)
    b = float(upper)
    if a == b:
        return 0.0
    sign = 1.0
    if a > b:
        a, b = b, a
        sign = -1.0
    estimate, error = _gk_panel(func, a, b)
    panels = [(estimate, error)]
    total = estimate
    total_error = error
    stack = [(a, b)]
    while total_error > max(float(abs_tol), float(rel_tol) * abs(total)) and len(stack) < int(subdivisions):
        index = max(range(len(panels)), key=lambda i: panels[i][1])
        left, right = stack.pop(index)
        piece, piece_error = panels.pop(index)
        mid = 0.5 * (left + right)
        q1, e1 = _gk_panel(func, left, mid)
        q2, e2 = _gk_panel(func, mid, right)
        total = total - piece + q1 + q2
        total_error = total_error - piece_error + e1 + e2
        stack.append((left, mid))
        stack.append((mid, right))
        panels.append((q1, e1))
        panels.append((q2, e2))
    return sign * total


def _gk_panel(func, a, b):
    half = 0.5 * (b - a)
    mid = 0.5 * (a + b)
    y15 = np.asarray(func(mid + half * _N15), dtype=float).reshape(-1)
    y7 = np.asarray(func(mid + half * _N7), dtype=float).reshape(-1)
    q15 = half * float(np.sum(_W15 * y15))
    q7 = half * float(np.sum(_W7 * y7))
    return q15, abs(q15 - q7)


def _match_arg(method):
    if method is None:
        return _METHODS[0]
    if isinstance(method, (list, tuple)) and tuple(method) == _METHODS:
        return _METHODS[0]
    name = str(method)
    matches = [choice for choice in _METHODS if choice.startswith(name)]
    if len(matches) != 1:
        raise PracmaError('method should be one of "Kronrod", "Clenshaw", "Simpson"')
    return matches[0]


def _one(value):
    array = np.asarray(value)
    if np.iscomplexobj(array):
        array = np.asarray(array, dtype=complex).reshape(-1)
        return complex(array[0])
    return float(np.asarray(array, dtype=float).reshape(-1)[0])


def _scalar(value, name):
    if isinstance(value, (bool, np.bool_)):
        raise PracmaError(f"is.numeric({name}) is not TRUE")
    array = np.asarray(value)
    if array.size != 1 or np.iscomplexobj(array) or not np.issubdtype(array.dtype, np.number):
        raise PracmaError(f"is.numeric({name}) is not TRUE")
    return float(array.reshape(-1)[0])


def _callable(fun):
    if not callable(fun):
        raise PracmaError("argument is not a function")
    return fun
